const GAMA_BOOT_SCRIPTS = [{id: "flux", name: "Time circuits / flux capacitor", lines: [ "Alright, let's get this place running.", "First, turn on the time circuits.", "[Flips switch]", "Good, the readout is live.", "Where you're going.", "Where you are.", "Where you've been.", "Everything is tracking.", "Now, input destination coordinates.", "November 5, 1955.", "Perfect.", "Wait, watch that tracking dial.", "That's the plutonium decay rate.", "Got to keep an eye on that.", "Next, is the flux capacitor pulsing?", "Pulsing.", "Check.", "Now wind her up to exactly 88.", ],},{id: "openshop", name: "Cockpit checklist / opening up shop", lines: [ "Alright, let's open up shop.", "Auto-pilot?", "Engaged. Check.", "Heavy particles?", "Filtered. Check.", "Radar-range?", "Calibrated. Check.", "Blinkenlights?", "[Glances at console]", "Blinking. Check.", "Passive matrix?", "Switching to active. Check.", "Coffee maker?", "Brewing. Check.", "Artificial gravity?", "On. Wait. Off. Wait.", "Floating. Check.", ],},{id: "salvagebay", name: "Salvage bay cold open", lines: [ "Right. Let's get the bay open.", "Bring the floods up slow.", "[Ticking, then light]", "There she is.", "Hull pressure?", "Holding. Check.", "Scrubbers?", "Running. Check.", "Grapple arm, full extension.", "[Whine of servos]", "Little stiff on the elbow.", "It'll loosen up.", "Manifest board?", "Lit. Check.", "Anything on the long-range?", "Quiet.", "Good. Quiet's good.", "Okay. Open the doors.", ],},{id: "darkroom", name: "Darkroom / develop the plates", lines: [ "Okay. Doors shut, lock it.", "Safelight on.", "[Red glow]", "That's the one.", "Developer, sixty-eight degrees.", "Sixty-eight on the nose. Check.", "Stop bath?", "Poured. Check.", "Fixer?", "...Fixer.", "[Rummaging]", "Fixer. Check.", "Timer set. Agitate every thirty.", "Now we find out what we've got.", "Slide it in.", "And wait.", "Never gets old, this part.", ],},{id: "projectionist", name: "Projection booth, last show of the night", lines: [ "Last show. Let's thread her up.", "Lamp?", "Struck. Check.", "Give it a minute to come up.", "Gate clean?", "[Blows across it]", "Clean. Check.", "Loop above, loop below.", "Both good. Check.", "Sound head?", "Reading. Check.", "Changeover cue on reel two.", "Marked. Check.", "Douser open.", "House lights down.", "And... roll it.", ],},{id: "brew", name: "Witch's brew (Halloween)", season:{from: "10-01", to: "10-31"}, lines: [ "Alright. Let's get the pot on.", "Fire up. Not too high.", "[Crackle]", "There we go.", "Water to the second ring.", "Filled. Check.", "Eye of newt?", "Two. Check.", "Toe of frog?", "...We're out of toe of frog.", "Knee of frog. Nobody'll know.", "Check.", "Now stir. Widdershins only.", "Other way. Other way.", "There.", "Wool of bat, and a good scream.", "[Screams politely]", "Check.", "Now we let her bubble.", ],},{id: "sleigh", name: "Sleigh pre-flight (late December)", season:{from: "12-18", to: "12-26"}, lines: [ "Okay. One night. Let's go.", "Runners waxed?", "Waxed. Check.", "Bells?", "[Shakes them once]", "Bells. Check.", "Manifest loaded, north to south.", "Loaded. Check.", "Reindeer, count off.", "...That's seven.", "[Counts again]", "That's eight. Check.", "Nose?", "Lit. Check.", "Altitude on my mark.", "And we're off.", ],}, ];